insert into questions(id,level,difficulty,tags,image,situation,options,answer,spell,legal,source) values
(1,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Mèo Mít đặt mật khẩu game là "meomit123". Cún Bông khen: "Dễ nhớ ghê, cho tớ mượn nhé!". Mèo Mít nên làm gì?','["Viết mật khẩu lên bảng lớp để khỏi quên", "Cho mượn nhưng bắt Cún Bông hứa không kể ai", "Cho Cún Bông mượn vì bạn thân thì không sao", "Không cho ai biết mật khẩu, kể cả bạn thân, và đổi sang mật khẩu khó đoán hơn"]'::jsonb,3,'Mật khẩu như bàn chải đánh răng: không cho ai mượn!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(2,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Tí dán tờ giấy ghi mật khẩu ngay trên màn hình máy tính "cho tiện". Điều gì có thể xảy ra?','["Ai đi ngang qua cũng đọc được và đăng nhập vào tài khoản của Tí", "Chỉ mèo mới đọc được giấy dán", "Mật khẩu sẽ tự đổi sau 1 ngày", "Không sao vì máy tính biết chủ nhân là Tí"]'::jsonb,0,'Mật khẩu dán màn hình = chìa khóa treo ngoài cửa.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(3,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Một người lạ trong game nhắn: "Em dễ thương quá, cho anh xin địa chỉ nhà để gửi quà nhé!". Tí nên làm gì?','["Không trả lời, không cho địa chỉ, kể ngay với bố mẹ", "Cho địa chỉ trường thay vì địa chỉ nhà", "Hỏi quà gì rồi mới quyết định", "Cho địa chỉ nhà hàng xóm cho chắc"]'::jsonb,0,'Người lạ hỏi nhà – mình hỏi bố mẹ!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(4,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Cún Bông nhận tin nhắn: "Đây là bí mật của hai đứa mình thôi, đừng kể bố mẹ nhé!". Cún Bông nên nghĩ gì?','["Đợi tới sinh nhật rồi mới kể", "Kể cho mỗi bạn mèo hàng xóm thôi", "Bí mật khiến mình sợ không phải bí mật cần giữ – kể ngay với người lớn tin cậy", "Giữ bí mật vì đã hứa rồi"]'::jsonb,2,'Bí mật làm mình sợ là bí mật phải kể!','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(5,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Tí chụp ảnh cả lớp đang ngủ gật và muốn đăng lên mạng cho "vui". Tí nên làm gì?','["Đăng lúc nửa đêm để ít người xem", "Đăng rồi xóa sau 5 phút", "Đăng nhưng dán sticker lên mặt một bạn", "Không đăng khi các bạn chưa đồng ý"]'::jsonb,3,'Ảnh bạn là của bạn – muốn đăng phải hỏi!','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(6,1,1,ARRAY['link-la']::text[],'img/linkla.svg','Mèo Mít nhận tin nhắn: "Bấm vào đây nhận 1 triệu kim cương miễn phí!!!". Mèo Mít nên làm gì?','["Gửi cho cả lớp cùng nhận", "Bấm thử một lần thôi", "Không bấm, hỏi bố mẹ hoặc thầy cô", "Bấm bằng điện thoại của mẹ cho an toàn"]'::jsonb,2,'Quà miễn phí trên mạng thường là cái bẫy có nơ.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(7,1,1,ARRAY['link-la']::text[],'img/linkla.svg','Máy tính báo: "Máy bạn có 99 con virus! Tải ngay phần mềm diệt virus này!". Tí nên làm gì?','["Rút điện máy tính rồi cắm lại và tải", "Tải ngay kẻo virus lây sang Tí", "Không tải, đóng trang và nhờ người lớn kiểm tra", "Bấm \"Đồng ý\" thật nhanh nhiều lần"]'::jsonb,2,'Bảng cảnh báo hù dọa = cửa sau của kẻ xấu.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(8,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Cún Bông đọc tin: "Ngày mai trường nghỉ học vì có khủng long!". Cún Bông muốn chia sẻ ngay. Nên làm gì?','["Hỏi thầy cô hoặc bố mẹ trước, không chia sẻ tin chưa kiểm chứng", "Đăng thêm ảnh khủng long cho thật", "Chia sẻ ngay cho bạn bè được nghỉ", "Chia sẻ kèm chữ \"nghe nói thôi nha\""]'::jsonb,0,'Chưa chắc thì chưa share!','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(9,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Trong nhóm chat lớp, các bạn chế ảnh Tí thành con heo và cười ầm. Mèo Mít nên làm gì?','["Thả \"haha\" cho hòa đồng", "Không thả \"haha\", không chia sẻ tiếp, báo thầy cô", "Chế thêm ảnh khác cho vui hơn", "Im lặng rời nhóm và quên đi"]'::jsonb,1,'“Chỉ đùa thôi” không xóa được tổn thương.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(10,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Mèo Mít bị trêu chọc trên mạng và thấy rất buồn. Mèo Mít nên làm gì?','["Xóa hết tài khoản và không nói với ai", "Tự chịu đựng vì kể ra sẽ bị cười", "Kể với bố mẹ, thầy cô hoặc gọi Tổng đài 111", "Trêu lại thật nặng"]'::jsonb,2,'Không ai phải một mình – có số 111.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(11,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Tí muốn tự lập tài khoản mạng xã hội riêng dù mới 9 tuổi. Theo luật, ai đăng ký tài khoản cho Tí?','["Không ai cả, cứ dùng tài khoản của anh họ", "Bố mẹ hoặc người giám hộ đăng ký bằng thông tin của bố mẹ và giám sát", "Tí tự đăng ký và khai tăng tuổi", "Bạn lớp trên đăng ký hộ"]'::jsonb,1,'Trẻ em lên mạng có bố mẹ “cầm lái”.','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(12,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một trang web đố vui hỏi: "Nhập tên, số nhà, trường và số điện thoại của mẹ để biết bạn là siêu nhân nào!". Tí nên làm gì?','["Nhập thông tin của bạn thân", "Nhập hết vì muốn biết là siêu nhân nào", "Không nhập thông tin cá nhân, hỏi bố mẹ", "Chỉ nhập số điện thoại của bố"]'::jsonb,2,'Đố vui đòi số nhà = đố… kẻ gian vui.','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(13,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Đâu là thông tin cá nhân cần giữ kín, không đăng lên mạng?','["Địa chỉ nhà và số điện thoại", "Món ăn em thích nhất", "Màu yêu thích", "Tên con mèo trong phim hoạt hình"]'::jsonb,0,'Số nhà, số điện thoại – cất trong tủ, khóa kỹ!','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(14,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Bạn mới quen trong game rủ Cún Bông gặp nhau ở công viên, "đừng nói với ai nhé". Cún Bông nên làm gì?','["Đi nhưng mang theo ô", "Rủ thêm một bạn nhỏ đi cùng", "Đi một mình cho bí mật", "Không đi, kể với bố mẹ ngay"]'::jsonb,3,'Bạn mạng rủ gặp riêng – báo ngay người lớn.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(15,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Người lạ gọi video và bảo Tí: "Bật camera lên cho anh xem phòng em nào". Tí nên làm gì?','["Hỏi người đó tên gì trước", "Bật một chút rồi tắt", "Bật camera hướng lên trần nhà", "Tắt cuộc gọi, chặn và kể với người lớn"]'::jsonb,3,'Camera của em – em có quyền nói KHÔNG.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(16,1,2,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Mèo Mít thấy bức tranh rất đẹp trên mạng, muốn đăng lại và ghi "Tranh của tớ vẽ". Như vậy có đúng không?','["Không đúng – phải ghi rõ tác giả, không nhận của người khác là của mình", "Đúng, vì tranh đã có trên mạng là của chung", "Đúng nếu tô thêm một màu", "Đúng nếu đăng lúc ít người xem"]'::jsonb,0,'Của ai trả nấy – kể cả trên mạng.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(17,1,1,ARRAY['game']::text[],'img/game.svg','Cún Bông chơi game tới 11 giờ đêm, mắt đỏ như thỏ. Lời khuyên nào đúng nhất?','["Đặt giờ chơi hợp lý với bố mẹ và đi ngủ đúng giờ", "Chơi tiếp để lên cấp nhanh hơn", "Chơi dưới chăn để bố mẹ không biết", "Uống nước ngọt cho tỉnh táo"]'::jsonb,0,'Game có “máu”, mắt cũng có “máu” – nghỉ đúng giờ!','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(18,1,1,ARRAY['link-la']::text[],'img/linkla.svg','Một tin nhắn từ số lạ: "Con của bạn đã trúng thưởng xe đạp, bấm link điền thông tin". Tí đọc được trên máy mẹ. Tí nên?','["Bấm giúp mẹ cho nhanh", "Chuyển tiếp cho bố", "Trả lời \"Có ạ!\"", "Đưa mẹ xem và nhắc mẹ không bấm link lạ"]'::jsonb,3,'Trúng thưởng bất ngờ – nghi ngờ trước tiên!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(19,1,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Gặp nội dung đáng sợ trên mạng, 5 "nút" cần nhớ là gì?','["Chụp lại – Gửi cả lớp – Đăng – Câu like – Xóa", "Tắt máy – Ngủ – Quên – Không kể – Chơi tiếp", "Dừng – Không lan truyền – Lưu bằng chứng – Báo cáo – Chia sẻ với người tin cậy", "Xem tiếp – Chia sẻ – Bình luận – Thả tim – Quên"]'::jsonb,2,'5 nút vàng: Dừng, Không lan, Lưu, Báo, Chia.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(20,1,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Số điện thoại Tổng đài quốc gia bảo vệ trẻ em là gì?','["115", "111", "113", "114"]'::jsonb,1,'Một – một – một: một cuộc gọi, một người bạn.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(21,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Mật khẩu nào an toàn nhất cho tài khoản của Tí?','["123456", "tiyeumeo", "Mot_Con-Vit!Xoe2CanhVang", "ngày sinh của Tí"]'::jsonb,2,'Mật khẩu xịn: dài, lạ, có chữ có số có ký hiệu.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(22,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Bố đăng ảnh Cún Bông tắm bồn lên mạng. Cún Bông thấy ngại. Cún Bông nên làm gì?','["Nói với bố rằng mình không thích và xin bố gỡ ảnh", "Im lặng vì bố là người lớn", "Đăng lại ảnh bố ngủ ngáy để trả đũa", "Khóa tài khoản của bố"]'::jsonb,0,'Em có quyền nói về ảnh của chính mình.','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(23,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Trên mạng có video "Ăn 10 cái kẹo mỗi ngày sẽ cao thêm 10cm". Mèo Mít nên?','["Không tin ngay, hỏi thầy cô, bố mẹ", "Ăn ngay 20 cái cho cao gấp đôi", "Mua kẹo cho cả nhà", "Chia sẻ cho cả lớp cùng cao"]'::jsonb,0,'Nghe lạ tai – hỏi người lớn rồi hãy tin.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(24,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Một tài khoản tự xưng là "thầy giáo mới" nhắn riêng, xin ảnh và địa chỉ của Tí. Tí nên?','["Hỏi lại thầy cô chủ nhiệm và bố mẹ, không gửi gì", "Gửi ngay vì là thầy giáo", "Gửi địa chỉ nhưng không gửi ảnh", "Gửi ảnh nhưng không gửi địa chỉ"]'::jsonb,0,'Xưng “thầy” trên mạng – kiểm tra ngoài đời!','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(25,1,2,ARRAY['ai-deepfake']::text[],'img/deepfake.svg','Cún Bông thấy video "chú mèo nói tiếng người, kêu gọi các bạn chuyển tiền mua cá". Đây có thể là gì?','["Phim hoạt hình chính thức của trường", "Video giả do máy tính tạo ra để lừa người xem", "Chú mèo thông minh thật", "Tin tức nghiêm túc"]'::jsonb,1,'Thấy là tin? Chưa chắc – máy cũng biết “diễn”.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(26,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Mèo Mít dùng máy tính ở thư viện, xong việc thì đi về luôn. Mèo Mít quên làm gì?','["Chỉnh ghế", "Đăng xuất tài khoản", "Tắt màn hình", "Lau bàn phím"]'::jsonb,1,'Dùng máy chung – xong việc nhớ “đăng xuất”.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(27,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí lỡ gửi tin nhắn chê bai bạn trong nhóm, giờ thấy hối hận. Tí nên làm gì?','["Rời nhóm và giả vờ không biết", "Gửi thêm tin để chữa cháy bằng chê người khác", "Đổ cho em trai gửi", "Dừng lại, xóa tin và xin lỗi bạn"]'::jsonb,3,'Lỡ làm sai – dừng lại và xin lỗi.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(28,1,1,ARRAY['game']::text[],'img/game.svg','Trong game, người lạ tặng Cún Bông nhiều vật phẩm rồi bảo "giờ em gửi ảnh cho anh nhé". Cún Bông nên?','["Gửi ảnh của bạn khác", "Từ chối, chặn người đó và kể với người lớn", "Gửi ảnh vì đã nhận quà rồi", "Trả lại vật phẩm rồi gửi ảnh"]'::jsonb,1,'Quà trong game không phải vé đòi ảnh.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(29,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Lớp có danh sách học sinh kèm số điện thoại phụ huynh. Mèo Mít muốn đăng công khai lên trang cá nhân. Có nên không?','["Không, vì đó là thông tin cá nhân của người khác", "Có, cho các bạn dễ liên lạc", "Có, vì danh sách là của lớp", "Có, nếu chỉ đăng một nửa"]'::jsonb,0,'Thông tin bạn bè – tôn trọng như của mình.','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(30,1,1,ARRAY['link-la']::text[],'img/linkla.svg','USB nhặt được ở sân trường có ghi "Đáp án kiểm tra". Tí nên làm gì?','["Không cắm vào máy, nộp cho thầy cô", "Cắm vào máy xem ngay", "Cắm vào máy của bạn cho an toàn", "Mang về nhà cắm vào máy bố"]'::jsonb,0,'USB lạ – có thể chứa “virus bất ngờ”.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(31,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Mèo Mít nghe tin đồn "bạn Na bị bệnh lây, đừng chơi với Na" trong nhóm chat. Mèo Mít nên?','["Chia sẻ để cảnh báo mọi người", "Không lan truyền, hỏi thầy cô và bênh vực bạn", "Rời xa bạn Na ngay", "Thêm chi tiết cho câu chuyện hấp dẫn"]'::jsonb,1,'Tin đồn làm đau bạn – dừng ở mình.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(32,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Khi không học online, nên làm gì với camera máy tính?','["Tắt hoặc che camera lại", "Dán sticker hình mặt cười lên màn hình", "Luôn bật để tiện", "Hướng camera ra cửa sổ"]'::jsonb,0,'Camera nghỉ thì che – kẻ xấu hết “nghía”.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(33,1,1,ARRAY['mua-sam']::text[],'img/muasam.svg','Cún Bông thấy quảng cáo game: "Nhập số thẻ ngân hàng của bố để nhận skin miễn phí". Nên làm gì?','["Nhập một nửa số thẻ", "Nhập số thẻ của mẹ thay vì bố", "Lấy thẻ bố nhập nhanh", "Không nhập, báo bố mẹ"]'::jsonb,3,'Đã miễn phí sao lại đòi thẻ ngân hàng?','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(34,1,2,ARRAY['mat-khau']::text[],'img/matkhau.svg','Tí dùng chung một mật khẩu cho tất cả tài khoản. Nếu một tài khoản bị lộ thì sao?','["Máy tính sẽ tự đổi mật khẩu", "Chỉ tài khoản đó bị ảnh hưởng", "Kẻ xấu có thể mở được tất cả tài khoản khác", "Không sao vì mật khẩu dài"]'::jsonb,2,'Một chìa mở mọi cửa – mất là mất hết!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(35,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Ai là người Tí nên tìm khi gặp chuyện không ổn trên mạng?','["Một tài khoản ẩn danh", "Người lạ trong game", "Bố mẹ, thầy cô hoặc người lớn tin cậy", "Không ai cả, tự xử lý"]'::jsonb,2,'Chuyện trên mạng – có người lớn đồng hành.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(36,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Cún Bông muốn gửi ảnh mặc đồ ngủ cho "bạn mới quen trên mạng". Nên làm gì?','["Gửi ảnh mờ thôi", "Không gửi ảnh riêng tư cho ai trên mạng", "Gửi vì bạn khen dễ thương", "Gửi rồi bảo bạn xóa"]'::jsonb,1,'Riêng tư không phải thứ để chia sẻ.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(37,1,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Khi bị người lạ nhắn tin đe dọa, điều gì KHÔNG nên làm?','["Xóa hết tin nhắn và giấu không cho ai biết", "Chặn và báo cáo tài khoản", "Kể với bố mẹ", "Chụp màn hình lưu bằng chứng"]'::jsonb,0,'Đừng xóa bằng chứng – hãy lưu và báo.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(38,1,1,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Mèo Mít tải phim lậu trên trang lạ để xem miễn phí. Rủi ro là gì?','["Phim sẽ hay hơn", "Vi phạm bản quyền và dễ dính phần mềm độc hại", "Máy sẽ chạy nhanh hơn", "Không có rủi ro gì"]'::jsonb,1,'Phim lậu – vừa sai luật vừa rước virus.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(39,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Có người nhắn: "Mình là quản trị game, cho mình mã đăng nhập (OTP) để tặng quà". Tí nên?','["Đưa một nửa mã", "Đưa ngay để nhận quà", "Hỏi tên rồi đưa", "Không đưa mã OTP cho bất kỳ ai"]'::jsonb,3,'OTP là “bí mật quốc gia” của riêng em.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(40,1,1,ARRAY['game']::text[],'img/game.svg','Bạn rủ Tí vào nhóm "hack game, có tiền thật". Tí nên?','["Tham gia để giàu nhanh", "Rủ thêm bạn để chia tiền", "Tham gia nhưng không nói ai", "Từ chối vì hack game là xâm nhập trái phép, có thể bị lừa"]'::jsonb,3,'Hack là phá khóa nhà người khác – không vui đâu.','Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(41,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một ứng dụng vẽ tranh xin quyền đọc danh bạ và vị trí. Mèo Mít nên?','["Cài thêm 3 ứng dụng nữa", "Cấp danh bạ, không cấp vị trí", "Hỏi bố mẹ, không cấp quyền không cần thiết", "Cấp hết cho nhanh"]'::jsonb,2,'App vẽ tranh cần bút – không cần danh bạ.','Điểm b khoản 3 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(42,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn Bin bị cả nhóm tẩy chay trên mạng. Cún Bông có thể giúp gì?','["Nhắn hỏi thăm Bin và báo thầy cô", "Cùng tẩy chay cho an toàn", "Không làm gì vì không phải việc của mình", "Chụp lại để gửi nhóm khác cười"]'::jsonb,0,'Một lời hỏi thăm có thể cứu cả một ngày.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(43,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Video "uống nước rửa chén sẽ thông minh hơn" đang lan truyền. Tí nên?','["Rủ bạn thử chung", "Chia sẻ cảnh báo kèm lời “thử xem”", "Không làm theo, không chia sẻ và báo người lớn", "Thử một ngụm"]'::jsonb,2,'Thử thách nguy hiểm – bấm nút DỪNG.','Điểm d khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(44,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Tí học online, nhóm lớp bảo bật camera. Một người lạ vào phòng học online. Tí nên?','["Trò chuyện với người lạ", "Báo thầy cô ngay để mời người lạ ra", "Gửi link phòng cho người lạ khác", "Tắt mic và mặc kệ"]'::jsonb,1,'Phòng học online cũng cần “bảo vệ cửa”.','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(45,1,2,ARRAY['link-la']::text[],'img/linkla.svg','Email "Từ: Hiệu trưởng" nhưng địa chỉ là thaihieutruong99@abcxyz.top, yêu cầu tải file "diem.exe". Tí nên?','["Mở bằng điện thoại", "Không mở file, báo thầy cô", "Chuyển cho bạn mở trước", "Tải về xem điểm"]'::jsonb,1,'Tên quen, địa chỉ lạ – đuôi .exe là báo động!','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(46,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Mẹ hỏi mật khẩu tài khoản học tập của Tí để giúp Tí. Có được nói không?','["Nói với người lạ trong game", "Không bao giờ nói với ai, kể cả bố mẹ", "Được nói với bố mẹ – người giám hộ, nhưng không nói với người khác", "Nói với bạn thân trước"]'::jsonb,2,'Bố mẹ là “đồng đội” – người lạ thì không.','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(47,1,1,ARRAY['mua-sam']::text[],'img/muasam.svg','Tí thấy quảng cáo "Điện thoại xịn chỉ 10.000 đồng, chuyển khoản trước". Nên nghĩ gì?','["Mua 10 cái tặng cả lớp", "Chuyển tiền của heo đất", "Rẻ bất thường – có thể là lừa đảo", "Mua ngay kẻo hết"]'::jsonb,2,'Rẻ như cho – cẩn thận bị cho… vào bẫy.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(48,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Cún Bông đăng ảnh check-in kèm "đang ở nhà một mình". Có vấn đề gì?','["Ảnh sẽ được nhiều tim hơn", "Kẻ xấu biết em ở đâu và đang ở một mình", "Không có vấn đề gì", "Bạn bè sẽ tới chơi"]'::jsonb,1,'Đừng “báo cáo” vị trí cho cả thế giới.','Khoản 1 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(49,1,1,ARRAY['ai-deepfake']::text[],'img/deepfake.svg','Tí nhận cuộc gọi video giống hệt mẹ, nói: "Con gửi mã số trên thẻ của bố cho mẹ". Tí nên?','["Hỏi mẹ ăn cơm chưa rồi gửi", "Cúp máy, gọi lại cho mẹ bằng số quen để hỏi", "Gửi cho bố trước", "Gửi ngay vì đúng là mặt mẹ"]'::jsonb,1,'Mặt giống chưa chắc là người thật – gọi lại kiểm tra.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(50,1,1,ARRAY['game']::text[],'img/game.svg','Tí bị "mất nick" game. Ai đó đòi tiền để trả lại. Tí nên?','["Hack lại tài khoản kẻ đó", "Đăng lên mạng chửi kẻ đó", "Chuyển tiền ngay", "Báo bố mẹ, không chuyển tiền, báo nhà phát hành game"]'::jsonb,3,'Bị đòi tiền chuộc nick – không trả, hãy báo!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(51,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Lời mời kết bạn từ "Siêu nhân Gao Đỏ chính hãng". Mèo Mít nên?','["Kết bạn cả Gao Xanh", "Chấp nhận rồi hỏi số điện thoại", "Chấp nhận ngay vì thích Gao Đỏ", "Không chấp nhận người lạ, dù tên nghe vui"]'::jsonb,3,'Tên ngầu chưa chắc người ngoan.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(52,2,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Nhóm lớp lan truyền "Mai thi học kỳ bị hoãn, nguồn: tin chuẩn 100%". Không ai biết ai đăng đầu tiên. Bạn nên?','["Chia sẻ thêm vào 5 nhóm khác cho chắc", "Chia sẻ vì \"tin chuẩn 100%\"", "Nghỉ ôn bài luôn", "Kiểm tra trên kênh chính thức của trường trước khi tin hay chia sẻ"]'::jsonb,3,'“Chuẩn 100%” mà không nguồn = 0% đáng tin.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(53,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí lập "page confession" đăng chuyện xấu bịa về bạn cùng lớp cho vui. Hành vi này là?','["Bịa đặt, xúc phạm danh dự người khác – bị nghiêm cấm", "Quyền tự do sáng tác", "Hợp pháp nếu ẩn danh", "Đùa vui vô hại"]'::jsonb,0,'Ẩn danh không phải áo tàng hình trước pháp luật.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(54,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Bạn gửi riêng cho Mèo Mít ảnh nhạy cảm của một bạn khác, kèm "xem xong xóa nhé". Mèo Mít nên?','["Xem rồi xóa là xong", "Không xem, không chuyển tiếp, báo người lớn tin cậy", "Chuyển cho một người thôi", "Lưu lại phòng khi cần"]'::jsonb,1,'Mỗi lượt chuyển là thêm một vết thương.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(55,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Nhóm bạn dùng app AI ghép mặt cô giáo vào clip nhảy múa hài rồi đăng lên TikTok. Đánh giá?','["Hợp pháp nếu có chữ \"AI\"", "Dùng AI giả mạo hình ảnh người khác trái luật là hành vi bị nghiêm cấm", "Chỉ là sáng tạo nội dung", "Không sao nếu cô không biết"]'::jsonb,1,'Ghép mặt người khác – ghép luôn rắc rối pháp lý.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm h khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(56,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Bạn rủ "cho mượn tài khoản ngân hàng của mẹ để nhận tiền hộ, được trả 200k". Cún Bông nên?','["Đồng ý một lần thôi", "Từ chối – cho mượn, mua bán tài khoản ngân hàng là trái luật", "Hỏi mẹ mượn thẻ lén", "Đồng ý vì có tiền"]'::jsonb,1,'Cho thuê tài khoản = thuê luôn rắc rối.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(57,2,1,ARRAY['link-la']::text[],'img/linkla.svg','Tin nhắn Facebook từ bạn thân: "Bình chọn giúp tớ nhé!" kèm link yêu cầu đăng nhập Facebook lần nữa. Bạn nên?','["Không đăng nhập, gọi hỏi bạn – có thể tài khoản bạn đã bị chiếm", "Đăng nhập để giúp bạn", "Đăng nhập bằng tài khoản phụ", "Gửi link cho cả lớp bình chọn"]'::jsonb,0,'Link đòi đăng nhập lại – dấu hiệu câu “cá”.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm c khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(58,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','App "xem ai vào trang cá nhân bạn" đòi tên đăng nhập và mật khẩu Facebook. Tí nên?','["Cung cấp vì tò mò", "Không cung cấp, đây là chiêu thu thập dữ liệu trái phép", "Cung cấp tài khoản của bạn khác", "Cung cấp rồi đổi mật khẩu sau 1 tháng"]'::jsonb,1,'Tò mò ai xem mình – kẻ gian đang xem mình!','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(59,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí bị nhắn tin xúc phạm liên tục. Bước nào là ĐÚNG để lưu bằng chứng?','["Chỉnh ảnh cho rõ ràng hơn", "Xóa tin để quên", "Chửi lại rồi chụp", "Chụp màn hình có thời gian, tài khoản gửi, không chỉnh sửa"]'::jsonb,3,'Bằng chứng nguyên vẹn – bảo vệ chính mình.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(60,2,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Bài đăng "Uống 3 lít nước chanh mỗi sáng chữa khỏi mọi bệnh" có 1 triệu like. Nhiều like có nghĩa là?','["Chắc chắn đúng", "Đúng một nửa", "Đúng nếu bác sĩ like", "Không có nghĩa là đúng – cần kiểm chứng nguồn y tế tin cậy"]'::jsonb,3,'Like nhiều không thay được bằng chứng.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(61,2,2,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Mèo Mít đăng lại nguyên video của YouTuber khác lên kênh mình để kiếm tiền. Đây là?','["Hợp pháp vì video đã công khai", "Được phép nếu thêm nhạc", "Hợp pháp nếu đổi tiêu đề", "Vi phạm bản quyền trên không gian mạng"]'::jsonb,3,'Copy-paste kiếm tiền = copy-paste rắc rối.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(62,2,1,ARRAY['game']::text[],'img/game.svg','Trang web "cá cược game, nạp 50k ăn 500k" mời Tí tham gia. Đúng hay sai?','["Đúng vì chỉ là game", "Sai – tổ chức, tham gia đánh bạc qua mạng là bị nghiêm cấm", "Đúng nếu nạp ít", "Đúng nếu thắng"]'::jsonb,1,'“Nạp ít ăn nhiều” – thường là ăn sạch.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(63,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Người quen qua mạng dọa: "Không gửi thêm ảnh thì tao phát tán ảnh cũ". Bạn nên làm gì?','["Gửi thêm để họ im", "Dừng liên lạc, không gửi thêm, lưu bằng chứng, báo người lớn/công an", "Trả tiền cho họ", "Tự tìm nhà họ để nói chuyện"]'::jsonb,1,'Bị dọa ảnh – không gửi, không trả, báo ngay!','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(64,2,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Tính năng nào giúp tài khoản an toàn hơn ngay cả khi lộ mật khẩu?','["Đăng nhiều bài", "Xác thực hai yếu tố (2FA)", "Đặt tên tài khoản dài", "Ảnh đại diện đẹp"]'::jsonb,1,'Hai lớp khóa – kẻ gian bó tay.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(65,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một nhóm Zalo bán "danh sách số điện thoại học sinh cả trường". Việc mua bán này?','["Được phép nếu dùng để quảng cáo", "Hợp pháp nếu giá rẻ", "Bị nghiêm cấm – mua bán dữ liệu cá nhân trái luật", "Hợp pháp vì số điện thoại ai cũng có"]'::jsonb,2,'Dữ liệu người khác không phải món hàng.','Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(66,2,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn thấy livestream đánh nhau của học sinh trường mình. Hành động đúng?','["Không chia sẻ, báo cáo nội dung và báo thầy cô", "Bình luận cổ vũ", "Share ngay để mọi người biết", "Tải về lưu làm kỷ niệm"]'::jsonb,0,'Share bạo lực = tiếp tay bạo lực.','Điểm d khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(67,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Clip "giọng ca sĩ nổi tiếng" quảng cáo app vay tiền siêu nhanh. Bạn nên nghĩ gì?','["App chắc chắn uy tín", "Ca sĩ đã quảng cáo thật", "Có thể là giọng nói giả bằng AI để lừa đảo", "Vay thử 1 triệu"]'::jsonb,2,'Giọng quen chưa chắc người quen.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(68,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Tài khoản của Tí bị kẻ xấu chiếm và dùng đi lừa bạn bè. Điều Tí nên làm đầu tiên?','["Đi lừa lại kẻ xấu", "Lập tài khoản mới và im lặng", "Báo bạn bè cảnh giác, khôi phục tài khoản và báo người lớn", "Kệ, không phải lỗi mình"]'::jsonb,2,'Mất nick – báo ngay cho bạn bè đừng mắc bẫy.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(69,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Ảnh bão "khủng khiếp nhất lịch sử" đang lan truyền nhưng thật ra là ảnh từ phim. Người chia sẻ có thể bị gì?','["Có thể bị xử lý vì phát tán thông tin sai sự thật gây hoang mang", "Được thưởng vì cảnh báo sớm", "Chỉ người làm phim chịu trách nhiệm", "Không sao vì chỉ chia sẻ"]'::jsonb,0,'Share bừa – có thể bị phạt thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật); Nghị định 330/2026/NĐ-CP (xử phạt VPHC lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân)','ORIGINAL'),
(70,2,1,ARRAY['link-la']::text[],'img/linkla.svg','Tin nhắn "Tài khoản ngân hàng của bạn bị khóa, bấm link để mở" gửi tới máy mẹ. Bạn nên khuyên mẹ?','["Không bấm link, gọi tổng đài chính thức của ngân hàng", "Trả lời tin nhắn hỏi lý do", "Bấm và nhập mật khẩu nhanh", "Chuyển tiền sang tài khoản khác qua link"]'::jsonb,0,'Ngân hàng không nhắn link đòi mật khẩu.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(71,2,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','"Anh" quen qua game chuyển sang Telegram, khen Mèo Mít "trưởng thành hơn tuổi", dặn đừng kể ai. Đây là dấu hiệu?','["Anh ấy chỉ thân thiện", "Tình bạn đẹp", "Dụ dỗ trực tuyến – cần dừng lại và kể với người lớn", "Bình thường trên mạng"]'::jsonb,2,'Khen + bí mật + chuyển app = 3 đèn đỏ.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(72,2,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn đăng ảnh thẻ học sinh có đầy đủ họ tên, ngày sinh, mã số. Rủi ro?','["Được nhiều bạn kết bạn", "Bị lợi dụng giả mạo danh tính", "Không có rủi ro", "Trường khen"]'::jsonb,1,'Ảnh giấy tờ lên mạng – danh tính bay đi.','Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(73,2,2,ARRAY['cookie']::text[],'img/cookie.svg','Trang web hỏi "Chấp nhận tất cả cookie?". Theo Luật BVDLCN, mạng xã hội phải cho bạn quyền gì?','["Bắt buộc chấp nhận", "Không có quyền gì", "Lựa chọn từ chối thu thập và chia sẻ cookie", "Chỉ được xem nếu chấp nhận"]'::jsonb,2,'Cookie không phải bánh – được quyền nói “không”.','Khoản 3 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(74,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Tí đăng ảnh chụp lén bạn đang khóc trong nhà vệ sinh lên story. Đánh giá?','["Hợp pháp nếu không ghi tên", "Không sao nếu story 24h", "Xâm phạm đời sống riêng tư, danh dự của bạn", "Ghi lại khoảnh khắc thật"]'::jsonb,2,'Story 24 giờ – tổn thương có thể cả đời.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(75,2,1,ARRAY['game']::text[],'img/game.svg','Trên nhóm game có người bán "tool hack" kèm file .exe. Nguy cơ?','["File có thể chứa mã độc, và hack game là hành vi trái luật", "Không nguy cơ gì", "Game sẽ chạy mượt hơn", "Được chơi miễn phí trọn đời"]'::jsonb,0,'Tool hack = hack ngược máy bạn.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(76,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí "chỉ like" một bài chế giễu bạn cùng lớp. Điều đó có ảnh hưởng không?','["Không, like thì vô hại", "Có – lượt tương tác giúp nội dung lan rộng, làm tổn thương thêm", "Chỉ comment mới ảnh hưởng", "Like là ủng hộ tự do ngôn luận"]'::jsonb,1,'Mỗi lượt like là thêm một cú đẩy.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(77,2,1,ARRAY['mua-sam']::text[],'img/muasam.svg','Shop online yêu cầu "chuyển khoản cọc 100%, không giao COD, không cho xem hàng". Bạn nên?','["Chuyển gấp đôi để được ưu tiên", "Cho shop mã OTP để thanh toán", "Chuyển ngay kẻo hết hàng", "Cảnh giác, kiểm tra uy tín shop hoặc chọn kênh an toàn hơn"]'::jsonb,3,'Cọc 100% với shop lạ – rủi ro 100%.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(78,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Có người dùng ảnh trên Facebook của chị Tí để tạo tài khoản giả, mượn tiền họ hàng. Hành vi này?','["Chỉ là trùng tên", "Mạo danh, giả mạo hình ảnh cá nhân – vi phạm pháp luật", "Chỉ là trò đùa", "Hợp pháp vì ảnh công khai"]'::jsonb,1,'Mượn mặt người khác để mượn tiền = lừa đảo.','Điểm h khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(79,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Mạng xã hội yêu cầu chụp ảnh căn cước của bạn để "xác thực tài khoản". Theo Luật BVDLCN?','["Luật không quy định", "Bắt buộc phải gửi", "Được gửi nếu là thẻ học sinh", "Nền tảng mạng xã hội không được yêu cầu ảnh, video chứa giấy tờ tùy thân để xác thực tài khoản"]'::jsonb,3,'Xác thực bằng ảnh căn cước – luật nói không.','Khoản 2 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(80,2,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Bạn thấy bài "Cô hiệu trưởng bị bắt" không có nguồn. Lựa chọn tốt nhất?','["Không bình luận, không chia sẻ, chờ thông tin chính thức", "Đăng lên nhóm phụ huynh", "Chia sẻ kèm dấu chấm hỏi", "Bình luận \"thật không?\" để kéo tương tác"]'::jsonb,0,'Dấu chấm hỏi không làm tin giả thành vô tội.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(81,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Nhóm lớp tạo bình chọn "Bạn xấu nhất lớp". Mèo Mít là lớp trưởng nên làm gì?','["Bình chọn cho vui", "Đề nghị xóa bình chọn và báo giáo viên", "Chụp lại gửi nhóm khác", "Đề cử chính mình để đùa"]'::jsonb,1,'Bình chọn chê bai = bắt nạt có hệ thống.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(82,2,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Wifi quán trà sữa miễn phí không mật khẩu. Bạn nên tránh làm gì khi dùng?','["Xem dự báo thời tiết", "Tra từ điển", "Đọc truyện tranh", "Đăng nhập ngân hàng hoặc nhập mật khẩu quan trọng"]'::jsonb,3,'Wifi miễn phí – đừng mở “két sắt”.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(83,2,2,ARRAY['link-la']::text[],'img/linkla.svg','File "Ảnh_kỷ_yếu.jpg.apk" gửi qua Zalo. Điều đáng ngờ là gì?','["Tên file quá dài", "Ảnh kỷ yếu luôn là apk", "Đuôi .apk là file cài ứng dụng, không phải ảnh – có thể là mã độc", "Không có gì đáng ngờ"]'::jsonb,2,'Ảnh mà đuôi .apk – ảnh… mã độc.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(84,2,2,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Bạn mua 1 tài khoản xem phim rồi bán lại mật khẩu cho 50 người. Đánh giá?','["Hợp pháp vì đã trả tiền", "Không ai biết nên không sao", "Kinh doanh thông minh", "Vi phạm bản quyền, có thể bị xử lý"]'::jsonb,3,'Một tài khoản, năm mươi rắc rối.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(85,2,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Bạn được hẹn "phỏng vấn làm mẫu ảnh online, lương cao", yêu cầu gửi ảnh mặc đồ bơi. Bạn nên?','["Gửi ảnh bạn thân", "Gửi để có việc", "Gửi ảnh cũ", "Từ chối, báo người lớn – đây là chiêu dụ dỗ phổ biến"]'::jsonb,3,'Việc nhẹ lương cao + ảnh đồ bơi = bẫy.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(86,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Cô giáo dùng bảng điểm có tên học sinh để làm ví dụ công khai trên Facebook. Học sinh có quyền gì?','["Không có quyền gì", "Yêu cầu xóa hoặc hạn chế xử lý dữ liệu cá nhân của mình", "Chỉ được tự đăng bảng điểm của cô", "Chỉ được khiếu nại khi đủ 18 tuổi"]'::jsonb,1,'Dữ liệu của em – em có quyền lên tiếng.','Điểm d khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(87,2,1,ARRAY['game']::text[],'img/game.svg','Tí nạp game bằng thẻ của bố mà không hỏi. Vấn đề là?','["Game sẽ hoàn tiền", "Dùng phương tiện thanh toán của người khác trái phép", "Không vấn đề vì là bố", "Chỉ sai nếu nạp nhiều"]'::jsonb,1,'Thẻ bố không phải ví của em.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(88,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Bạn tự dựng video "trường có ma" để câu view, khiến nhiều bạn sợ không dám đi học. Đánh giá?','["Không sao nếu được nhiều view", "Đăng tin sai sự thật gây hoang mang – có thể bị xử lý", "Sáng tạo nội dung bình thường", "Hợp pháp vì là giải trí"]'::jsonb,1,'View tăng, rắc rối cũng tăng.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(89,2,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Thấy tài khoản đăng ảnh xâm hại trẻ em, bạn nên?','["Tải về làm bằng chứng gửi nhóm lớp", "Bình luận chửi", "Chia sẻ để cảnh báo", "Không chia sẻ, báo cáo nền tảng và báo công an/Tổng đài 111"]'::jsonb,3,'Báo cáo, đừng lan truyền.','Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(90,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Bạn nhận tin nhắn thoại giống giọng bố: "Bố đang gấp, chuyển ngay 5 triệu vào số này". Cách xử lý?','["Chuyển ngay vì giọng giống", "Hỏi bố món ăn yêu thích qua tin nhắn đó", "Gọi lại bố hoặc người nhà qua số quen để xác minh", "Chuyển một nửa"]'::jsonb,2,'Giọng giống – xác minh trước, chuyển tiền sau (hoặc không).','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(91,2,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Bạn có quyền yêu cầu người khác gỡ ảnh của mình họ đăng mà chưa hỏi không?','["Không, đăng rồi là của họ", "Chỉ khi ảnh xấu", "Chỉ người nổi tiếng mới có quyền", "Có – chủ thể dữ liệu có quyền yêu cầu xóa dữ liệu cá nhân"]'::jsonb,3,'Ảnh của mình – mình có tiếng nói.','Điểm d khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(92,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','App học tiếng Anh tắt đi rồi mà vẫn liên tục lấy vị trí. Theo luật, nhà cung cấp app phải?','["Được lấy tự do", "Không cần thông báo", "Thông báo việc dùng dữ liệu vị trí và cho người dùng tùy chọn theo dõi vị trí", "Chỉ cần giấu trong điều khoản"]'::jsonb,2,'Vị trí của bạn – bạn bật tắt.','Điểm b khoản 3 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(93,2,1,ARRAY['link-la']::text[],'img/linkla.svg','Mã QR dán trên cột điện: "Quét để nhận học bổng 10 triệu". Bạn nên?','["Không quét, mã QR lạ có thể dẫn tới trang lừa đảo", "Chụp gửi bạn bè quét", "Quét ngay", "Quét bằng máy của mẹ"]'::jsonb,0,'QR lạ – đừng để điện thoại “ăn” bậy.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(94,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Mèo Mít nhận ra mình từng chia sẻ bài chế giễu bạn. Việc nên làm?','["Đăng thêm bài khác để át đi", "Đổ lỗi cho người đăng đầu", "Giả vờ không biết", "Gỡ bài, xin lỗi bạn, không tiếp tục lan truyền"]'::jsonb,3,'Lỡ làm sai – dừng lại, sửa sai.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(95,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Bạn bè hỏi mượn tài khoản Zalo để "nhắn tin cho crush". Nếu bạn ấy dùng để làm việc xấu, ai chịu trách nhiệm?','["Chủ tài khoản cũng có thể bị xử lý tùy mức độ", "Nhà mạng", "Không ai cả", "Chỉ người mượn"]'::jsonb,0,'Tài khoản của bạn – trách nhiệm của bạn.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(96,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Có bài viết kêu gọi tẩy chay một cửa hàng với thông tin bịa đặt. Theo luật, kêu gọi tẩy chay kiểu này?','["Quyền của người tiêu dùng", "Là thông tin xâm phạm quyền, lợi ích hợp pháp của tổ chức", "Hợp pháp nếu nhiều người đồng tình", "Không có quy định"]'::jsonb,1,'Tẩy chay bằng tin bịa – bịa thì sai.','Điểm b khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(97,2,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Dấu hiệu nào cho thấy bạn mạng có thể không như họ nói?','["Không bao giờ bật camera, hỏi nhiều chuyện riêng, đòi giữ bí mật", "Thích cùng game với bạn", "Có ảnh đại diện đẹp", "Nói chuyện lịch sự"]'::jsonb,0,'Không ai trên mạng giống hệt những gì họ nói.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(98,2,2,ARRAY['mua-sam']::text[],'img/muasam.svg','Livestream bán "iPhone xách tay giá 1 triệu, cam kết chính hãng". Theo luật, quảng cáo bán hàng giả, không rõ nguồn gốc trên mạng là?','["Hành vi xâm phạm trật tự, an toàn xã hội trên không gian mạng", "Khuyến mãi bình thường", "Kinh doanh hợp pháp", "Chỉ vi phạm khi bị tố"]'::jsonb,0,'Hàng giá “khó tin” – thường là “khó tin” thật.','Điểm h khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(99,2,2,ARRAY['game']::text[],'img/game.svg','Bạn tạo phần mềm làm sập server game của trường "cho vui". Hành vi này là?','["Không ai biết thì không sao", "Thử tài lập trình", "Hợp pháp vì là trường mình", "Tấn công mạng – gây gián đoạn hệ thống thông tin"]'::jsonb,3,'Làm sập để vui – vui ở đồn.','Điểm b khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(100,2,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Bạn nhận được tin nhắn đe dọa lúc 11 giờ đêm. Theo cẩm nang, bước đầu tiên là?','["Đăng lên mạng kể khổ", "Chửi lại cho bõ tức", "Trả lời để hỏi lý do", "Dừng lại và cắt nguồn gây hại (chặn, ngừng trả lời)"]'::jsonb,3,'Nút đầu tiên: DỪNG.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(101,2,2,ARRAY['ai-deepfake']::text[],'img/deepfake.svg','Bạn dùng AI tạo ảnh "bạn cùng lớp đang ăn trộm" để trêu. Hành vi này vi phạm?','["Không vi phạm vì ảnh là AI", "Dùng AI giả mạo hình ảnh và bịa đặt xúc phạm người khác", "Không vi phạm nếu ghi \"đùa\"", "Chỉ vi phạm nếu bạn ấy kiện"]'::jsonb,1,'Ảnh AI – hậu quả thật.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(102,2,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn có nghĩa vụ gì với dữ liệu cá nhân của chính mình theo Luật BVDLCN?','["Tự bảo vệ dữ liệu cá nhân của mình", "Giao cho người khác giữ hộ", "Không có nghĩa vụ gì", "Phải đăng công khai"]'::jsonb,0,'Luật dặn: tự giữ dữ liệu của mình trước.','Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(103,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một app học tập ghi: "Tiếp tục sử dụng nghĩa là bạn đồng ý cho chúng tôi bán dữ liệu cho đối tác". Theo Luật BVDLCN, cách "đồng ý" này?','["Hợp lệ nếu người dùng trên 16 tuổi", "Hợp lệ vì đã thông báo", "Hợp lệ nếu app miễn phí", "Không hợp lệ – sự đồng ý phải tự nguyện, rõ ràng, theo từng mục đích; im lặng không phải là đồng ý"]'::jsonb,3,'Im lặng ≠ đồng ý. Đồng ý phải rõ ràng.','Khoản 2 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm d khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(104,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Đăng ký CLB online yêu cầu đồng ý chung một nút cho cả "quản lý thành viên" và "gửi quảng cáo của nhà tài trợ". Điểm sai?','["Sai vì nút quá nhỏ", "Không được buộc đồng ý kèm các mục đích khác ngoài thỏa thuận", "Chỉ sai nếu thu phí", "Không sai gì"]'::jsonb,1,'Mỗi mục đích một lần đồng ý.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm b khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(105,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn đã đồng ý cho một app dùng dữ liệu, giờ muốn rút lại. Theo luật?','["Đã đồng ý thì không rút được", "Chỉ rút được khi app đóng cửa", "Phải ra tòa mới rút được", "Có quyền yêu cầu rút lại sự đồng ý, gửi bằng văn bản hoặc dạng điện tử kiểm chứng được"]'::jsonb,3,'Đồng ý được thì rút được.','Điểm b khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 2 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(106,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Rút lại sự đồng ý có làm các hoạt động xử lý dữ liệu TRƯỚC thời điểm rút trở nên trái luật không?','["Có, mọi xử lý trước đó đều trái luật", "Có, và app phải bồi thường tự động", "Tùy app quyết định", "Không – việc rút lại không áp dụng với hoạt động xử lý trước thời điểm yêu cầu"]'::jsonb,3,'Rút đồng ý là “từ nay”, không phải “từ xưa”.','Khoản 4 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(107,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật BVDLCN, việc nào sau đây bị nghiêm cấm (trừ trường hợp luật khác quy định)?','["Mua, bán dữ liệu cá nhân", "Tự đăng ảnh của mình", "Yêu cầu chỉnh sửa dữ liệu sai", "Đồng ý cho trường lưu hồ sơ"]'::jsonb,0,'Dữ liệu người khác – không mua, không bán.','Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(108,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật BVDLCN, "dữ liệu cá nhân" sau khi đã khử nhận dạng thì?','["Trở thành bí mật nhà nước", "Thuộc về người khử nhận dạng", "Vẫn là dữ liệu cá nhân nhạy cảm", "Không còn là dữ liệu cá nhân"]'::jsonb,3,'Khử nhận dạng xong – không còn “nhận ra ai”.','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 11 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(109,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn phát hiện thông tin sai về mình trong hồ sơ một trung tâm tiếng Anh. Quyền của bạn?','["Xem, chỉnh sửa hoặc yêu cầu chỉnh sửa dữ liệu cá nhân", "Chỉ phụ huynh có quyền xem", "Chỉ được chấp nhận", "Phải trả phí mới được xem"]'::jsonb,0,'Dữ liệu sai – có quyền sửa.','Điểm c khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(110,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một tạp chí tuổi teen muốn đăng chuyện đời tư của bạn 14 tuổi (có tên, ảnh). Theo Luật BVDLCN cần sự đồng ý của ai?','["Chỉ của bạn đó", "Chỉ của bố mẹ", "Của chính bạn đó (vì từ đủ 7 tuổi) và người đại diện theo pháp luật", "Của nhà trường"]'::jsonb,2,'Trẻ từ 7 tuổi – cả em và bố mẹ cùng gật đầu.','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(111,3,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Theo Luật An ninh mạng 2025, đăng thông tin sai sự thật gây hoang mang trong Nhân dân thuộc nhóm nào?','["Chỉ vi phạm nếu có trên 1.000 lượt chia sẻ", "Vi phạm đạo đức, không vi phạm luật", "Hành vi bị nghiêm cấm về an ninh mạng", "Quyền tự do biểu đạt không giới hạn"]'::jsonb,2,'Sai sự thật gây hoang mang – nằm trong danh sách cấm.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(112,3,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Nghị định nào trong 7 nghị định ngày 19/8/2026 chuyên về phòng, chống tin giả, tin sai sự thật?','["Nghị định 329/2026/NĐ-CP", "Nghị định 331/2026/NĐ-CP", "Nghị định 332/2026/NĐ-CP", "Nghị định 328/2026/NĐ-CP"]'::jsonb,3,'Tin giả? Nhớ “ba hai tám”.','Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(113,3,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Nghị định xử phạt vi phạm hành chính trong lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân là?','["Nghị định 327/2026/NĐ-CP", "Nghị định 332/2026/NĐ-CP", "Nghị định 330/2026/NĐ-CP", "Nghị định 333/2026/NĐ-CP"]'::jsonb,2,'Phạt thì “ba ba mươi”.','Nghị định 330/2026/NĐ-CP (xử phạt VPHC lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân)','ORIGINAL'),
(114,3,1,ARRAY['luat-chung']::text[],'img/luat.svg','Luật An ninh mạng số 116/2025/QH15 có hiệu lực từ ngày nào?','["10/12/2025", "01/01/2026", "19/8/2026", "01/7/2026"]'::jsonb,3,'Mùng 1 tháng 7 năm 2026 – luật mới “lên sóng”.','Khoản 1 Điều 44 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(115,3,1,ARRAY['luat-chung']::text[],'img/luat.svg','Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15 có hiệu lực từ ngày nào?','["01/01/2026", "26/6/2025", "01/7/2026", "01/01/2027"]'::jsonb,0,'Tết Dương lịch 2026 – dữ liệu được “bảo hiểm”.','Điều 38 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(116,3,2,ARRAY['luat-chung']::text[],'img/luat.svg','Khi Luật An ninh mạng 2025 có hiệu lực, hai luật nào hết hiệu lực?','["Luật Giao dịch điện tử và Luật Viễn thông", "Bộ luật Dân sự và Bộ luật Hình sự", "Luật An toàn thông tin mạng 2015 và Luật An ninh mạng 2018", "Luật Trẻ em và Luật Giáo dục"]'::jsonb,2,'Hai luật cũ “nghỉ hưu”, một luật mới thay.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(117,3,2,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Theo Luật ANM 2025, người dùng có trách nhiệm gì với tài khoản số của mình?','["Chỉ doanh nghiệp mới có trách nhiệm", "Bảo mật thông tin đăng ký, mở, quản lý, sử dụng tài khoản số", "Không có trách nhiệm gì", "Chia sẻ mật khẩu cho người thân quen"]'::jsonb,1,'Tài khoản số của ai – người đó giữ.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(118,3,3,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Tài khoản của bạn bị người khác mượn để lừa đảo. Theo Luật ANM 2025, hậu quả có thể là?','["Chủ tài khoản, người sử dụng có thể bị xử lý kỷ luật, xử phạt hoặc truy cứu và phải bồi thường nếu gây thiệt hại", "Không ai bị xử lý vì là tài khoản ảo", "Chỉ người mượn bị xử lý", "Chỉ bị nhắc nhở"]'::jsonb,0,'Cho mượn tài khoản – trả giá bằng trách nhiệm.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(119,3,2,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Thu thập, mua bán, trao đổi trái phép thông tin tài khoản ngân hàng, ví điện tử của người khác là?','["Giao dịch dân sự bình thường", "Chỉ vi phạm khi trên 10 tài khoản", "Hợp pháp nếu có giấy viết tay", "Hành vi xâm phạm an ninh quốc gia, trật tự, an toàn xã hội trên không gian mạng"]'::jsonb,3,'Tài khoản người khác – không phải hàng hóa.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(120,3,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Luật ANM 2025 quy định cụ thể về việc dùng AI để giả mạo video, hình ảnh, giọng nói của người khác như thế nào?','["Được phép nếu để giải trí", "Là hành vi bị nghiêm cấm khi trái quy định pháp luật", "Chỉ cấm với người nổi tiếng", "Không có quy định về AI"]'::jsonb,1,'AI giả mặt giả giọng – luật đã gọi tên.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(121,3,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Hành vi nào được Luật ANM 2025 liệt kê là thông tin xâm phạm quyền, lợi ích của cá nhân?','["Đánh giá 3 sao một quán ăn trung thực", "Xúc phạm danh dự, uy tín, nhân phẩm của người khác", "Bày tỏ không thích một bộ phim", "Góp ý lịch sự về bài làm"]'::jsonb,1,'Chê có văn hóa ≠ xúc phạm.','Điểm d khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(122,3,3,ARRAY['bat-nat']::text[],'img/batnat.svg','Bịa đặt rằng bạn khác phạm tội rồi tố cáo họ với cơ quan có thẩm quyền thì sao?','["Là thông tin xâm phạm quyền, lợi ích hợp pháp của cá nhân theo Luật ANM", "Là quyền tố cáo", "Hợp pháp nếu tố cáo qua mạng", "Chỉ là hiểu nhầm"]'::jsonb,0,'Tố cáo thật là quyền – tố cáo bịa là vi phạm.','Điểm g khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(123,3,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Theo Luật ANM 2025, trẻ em có những quyền gì trên không gian mạng?','["Tiếp cận thông tin, tham gia hoạt động xã hội, vui chơi, giải trí, bảo vệ bí mật cá nhân, đời sống riêng tư", "Chỉ được dùng mạng khi có giáo viên", "Chỉ được học online", "Không có quyền gì cho đến 18 tuổi"]'::jsonb,0,'Trẻ em online – có quyền và được bảo vệ.','Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(124,3,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Doanh nghiệp cung cấp mạng xã hội có trách nhiệm gì với nội dung gây hại cho trẻ em theo Luật ANM 2025?','["Chỉ cảnh báo người đăng", "Không có trách nhiệm", "Ngăn chặn chia sẻ và xóa bỏ thông tin gây nguy hại, xâm hại trẻ em", "Chỉ xóa khi có lệnh tòa"]'::jsonb,2,'Nền tảng phải “dọn rác” độc hại cho trẻ.','Điểm b khoản 3 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(125,3,2,ARRAY['link-la']::text[],'img/linkla.svg','Ai có trách nhiệm chủ động phòng ngừa phần mềm độc hại theo Luật ANM 2025?','["Cơ quan, tổ chức, cá nhân – tức là mọi người", "Chỉ người làm IT", "Chỉ công an", "Chỉ nhà mạng"]'::jsonb,0,'Mã độc – ai cũng phải đề phòng.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(126,3,2,ARRAY['hack']::text[],'img/hack.svg','Bạn tìm ra lỗ hổng web trường và tự ý xâm nhập để "đổi điểm giúp bạn". Theo Luật ANM?','["Xâm nhập trái phép hệ thống thông tin – hành vi bị nghiêm cấm", "Kỹ năng đáng khen", "Hợp pháp nếu không lấy tiền", "Hợp pháp nếu báo trường sau"]'::jsonb,0,'Phát hiện lỗ hổng – báo, đừng khai thác.','Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(127,3,2,ARRAY['hack']::text[],'img/hack.svg','Bạn phát hiện lỗ hổng bảo mật trên website của trường. Cách đúng?','["Bán thông tin lỗ hổng", "Thử khai thác để chứng minh", "Báo cho nhà trường/cơ quan có thẩm quyền, không khai thác", "Đăng lên mạng khoe"]'::jsonb,2,'Lỗ hổng: báo cáo, không khai thác.','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(128,3,3,ARRAY['hack']::text[],'img/hack.svg','Bán, tặng phần mềm có tính năng gây hại để dùng vào mục đích trái pháp luật thuộc nhóm hành vi nào?','["Chia sẻ mã nguồn mở", "Hành vi tấn công mạng và liên quan tới tấn công mạng", "Không bị điều chỉnh", "Kinh doanh phần mềm bình thường"]'::jsonb,1,'Bán vũ khí số – cũng là tấn công mạng.','Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(129,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật ANM 2025, thu thập, sử dụng, phát tán, kinh doanh trái pháp luật dữ liệu cá nhân của người khác là?','["Hành vi bị nghiêm cấm trên không gian mạng", "Hoạt động marketing bình thường", "Hợp pháp nếu dữ liệu đã công khai", "Chỉ vi phạm đạo đức"]'::jsonb,0,'Dữ liệu người khác – không phải “mỏ vàng” tự do.','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(130,3,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Cố ý nghe lén, ghi âm, ghi hình trái phép cuộc gọi trên không gian mạng là?','["Quyền lưu bằng chứng tùy ý", "Chỉ sai nếu đăng lên mạng", "Hợp pháp nếu là bạn bè", "Hành vi bị nghiêm cấm"]'::jsonb,3,'Ghi lén cuộc gọi – luật cấm rõ ràng.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(131,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Mạng xã hội muốn đọc tin nhắn của bạn để "gợi ý quảng cáo phù hợp" mà không hỏi. Theo Luật BVDLCN?','["Được nếu ghi trong điều khoản dài", "Được phép nếu ẩn danh", "Được phép vì miễn phí", "Không được đọc tin nhắn khi chưa có sự đồng ý, trừ trường hợp luật khác quy định"]'::jsonb,3,'Tin nhắn riêng – không đọc lén.','Khoản 5 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(132,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Mạng xã hội có nghĩa vụ gì về chính sách bảo mật theo Luật BVDLCN?','["Giữ bí mật chính sách", "Không có nghĩa vụ", "Công khai chính sách, giải thích cách thu thập, sử dụng, chia sẻ dữ liệu và cho người dùng cơ chế truy cập, chỉnh sửa, xóa", "Chỉ cung cấp cho cơ quan nhà nước"]'::jsonb,2,'Minh bạch là nghĩa vụ, không phải ân huệ.','Khoản 6 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(133,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Dữ liệu sinh trắc học (vân tay, khuôn mặt) được định nghĩa là gì?','["Mọi ảnh selfie có filter", "Mật khẩu dạng số", "Dữ liệu về sở thích ăn uống", "Dữ liệu về thuộc tính vật lý, đặc điểm sinh học cá biệt và ổn định để xác định một người"]'::jsonb,3,'Vân tay không đổi được như mật khẩu – giữ cẩn thận!','Khoản 2 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(134,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một phòng gym thu thập vân tay hội viên nhưng để thiết bị lưu trữ ai cũng truy cập được. Họ vi phạm nghĩa vụ gì?','["Không vi phạm vì vân tay không phải bí mật", "Bảo mật vật lý thiết bị, hạn chế quyền truy cập dữ liệu sinh trắc học", "Chỉ cần xin lỗi khách", "Chỉ vi phạm nếu bị hack"]'::jsonb,1,'Dữ liệu sinh trắc – khóa hai lớp.','Điểm a khoản 4 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(135,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn thấy dữ liệu của mình bị lạm dụng và gây thiệt hại. Quyền nào sau đây là của chủ thể dữ liệu?','["Không có quyền nào", "Khiếu nại, tố cáo, khởi kiện, yêu cầu bồi thường thiệt hại", "Chỉ được đăng lên mạng bóc phốt", "Tự xâm nhập hệ thống để xóa"]'::jsonb,1,'Bị hại dữ liệu – dùng đường pháp luật.','Điểm đ khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(136,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Khi thực hiện quyền của chủ thể dữ liệu, bạn phải tuân thủ nguyên tắc nào?','["Được làm mọi cách để bảo vệ dữ liệu mình", "Được công khai dữ liệu người khác để trả đũa", "Không có nguyên tắc nào", "Không xâm phạm quyền, lợi ích hợp pháp của Nhà nước, tổ chức, cá nhân khác"]'::jsonb,3,'Đòi quyền mình – không giẫm quyền người.','Điểm c khoản 3 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(137,3,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Bình luận bịa đặt về chất lượng một ngân hàng gây hoang mang, rút tiền ồ ạt. Luật ANM xếp hành vi này vào?','["Đăng tải thông tin bịa đặt, sai sự thật trong lĩnh vực tài chính, ngân hàng – bị nghiêm cấm", "Phản biện xã hội", "Bình luận cá nhân", "Không có quy định"]'::jsonb,0,'Tin đồn tài chính – có thể gây “bão” thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(138,3,2,ARRAY['mua-sam']::text[],'img/muasam.svg','Tổ chức, hỗ trợ vận hành sàn giao dịch tài sản số trái phép trên mạng được Luật ANM 2025 xếp vào?','["Hoạt động khởi nghiệp hợp pháp", "Không bị điều chỉnh", "Hành vi xâm phạm an ninh quốc gia, trật tự, an toàn xã hội trên không gian mạng", "Đầu tư cá nhân"]'::jsonb,2,'Sàn “ảo” – rắc rối thật.','Điểm e khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(139,3,2,ARRAY['luat-chung']::text[],'img/luat.svg','Theo Luật ANM 2025, việc phổ biến kiến thức an ninh mạng ưu tiên những đối tượng nào?','["Trẻ em, người cao tuổi, người khó khăn trong nhận thức", "Chỉ sinh viên IT", "Chỉ doanh nghiệp", "Chỉ cán bộ công an"]'::jsonb,0,'Người dễ bị tổn thương – được ưu tiên học trước.','Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(140,3,2,ARRAY['bao-cao']::text[],'img/baocao.svg','Theo Luật ANM 2025, cá nhân sử dụng không gian mạng có trách nhiệm gì khi phát hiện hành vi xâm phạm an ninh mạng?','["Đăng lên mạng bóc phốt trước", "Kịp thời cung cấp thông tin cho cơ quan có thẩm quyền, lực lượng bảo vệ an ninh mạng", "Tự xử lý bằng cách tấn công lại", "Im lặng cho an toàn"]'::jsonb,1,'Thấy xâm phạm – báo đúng nơi.','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(141,3,3,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn A đăng clip chế giễu ngoại hình bạn B. Nhiều người chia sẻ lại "cho vui". Người chia sẻ có liên quan trách nhiệm không?','["Không, chỉ người đăng đầu tiên", "Không, vì không bình luận gì", "Có thể – phát tán thông tin xâm phạm danh dự người khác cũng là hành vi bị cấm", "Chỉ khi chia sẻ quá 3 lần"]'::jsonb,2,'Đăng lại cũng là “phát tán”.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(142,3,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Tài khoản giả mạo trang thông tin điện tử của trường để thu tiền "học phí bổ sung". Đây là?','["Giả mạo trang thông tin điện tử của tổ chức – bị nghiêm cấm", "Quảng cáo hợp pháp", "Lỗi kỹ thuật", "Không vi phạm vì chưa thu được tiền"]'::jsonb,0,'Fanpage giả – học phí thật mất.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(143,3,2,ARRAY['game']::text[],'img/game.svg','Quảng cáo "app cá độ bóng đá uy tín" tràn ngập nhóm chat. Theo Luật ANM, tổ chức đánh bạc qua mạng là?','["Chỉ cấm người dưới 18", "Hành vi bị nghiêm cấm", "Hợp pháp nếu nhà cái ở nước ngoài", "Giải trí hợp pháp"]'::jsonb,1,'Cá độ online – thua cả tiền lẫn luật.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(144,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bên quyết định mục đích và phương tiện xử lý dữ liệu cá nhân được gọi là?','["Chủ thể dữ liệu cá nhân", "Bên kiểm soát dữ liệu cá nhân", "Bên thứ ba", "Bên xử lý dữ liệu cá nhân"]'::jsonb,1,'Ai quyết “để làm gì” – bên kiểm soát.','Khoản 7 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(145,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một công ty in thẻ học sinh theo hợp đồng với trường. Công ty này đóng vai trò gì?','["Cơ quan quản lý nhà nước", "Chủ thể dữ liệu", "Bên xử lý dữ liệu cá nhân", "Bên kiểm soát dữ liệu cá nhân"]'::jsonb,2,'Làm theo yêu cầu qua hợp đồng – bên xử lý.','Khoản 8 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(146,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','"Chủ thể dữ liệu cá nhân" là ai?','["Cơ quan công an", "Người thu thập dữ liệu", "Công ty lưu dữ liệu", "Người được dữ liệu cá nhân phản ánh"]'::jsonb,3,'Dữ liệu nói về ai – người đó là chủ thể.','Khoản 5 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(147,3,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Chiếm đoạt, cố ý làm lộ, làm mất dữ liệu cá nhân thuộc nhóm nào theo Luật BVDLCN?','["Không có quy định", "Hành vi bị nghiêm cấm", "Sơ suất được miễn trách", "Chỉ vi phạm hợp đồng"]'::jsonb,1,'Làm lộ dữ liệu người khác – cấm.','Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(148,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn cho người khác mượn căn cước, tài khoản để họ đăng ký sim, mở ví... rồi họ lừa đảo. Theo Luật BVDLCN?','["Không có quy định", "Cho người khác sử dụng dữ liệu cá nhân của mình để làm trái luật là bị nghiêm cấm", "Chỉ vi phạm nếu nhận tiền", "Không có lỗi vì chỉ cho mượn"]'::jsonb,1,'Cho mượn danh tính – mượn luôn rắc rối.','Khoản 5 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(149,3,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Theo cẩm nang, có nên hứa giữ bí mật tuyệt đối khi bạn kể mình bị xâm hại trực tuyến?','["Có, và tự giải quyết", "Không, mà kể cho cả lớp", "Không nên hứa tuyệt đối – cần đưa người lớn tin cậy vào cuộc để bảo vệ bạn", "Có, phải giữ bí mật tuyệt đối"]'::jsonb,2,'Giữ riêng tư, đừng giữ nỗi sợ một mình.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(150,3,2,ARRAY['luat-chung']::text[],'img/luat.svg','Luật ANM 2025 được Quốc hội ban hành ngày nào?','["26/6/2025", "01/7/2026", "10/12/2025", "19/8/2026"]'::jsonb,2,'Ngày 10/12/2025 – ngày luật “chào đời”.','Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(151,3,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Theo Luật ANM 2025, ai có trách nhiệm bảo đảm quyền của trẻ em, bảo vệ trẻ khi tham gia không gian mạng?','["Cơ quan, tổ chức, cha mẹ, người giám hộ, giáo viên, người chăm sóc và cá nhân liên quan", "Chỉ cha mẹ", "Chỉ công an", "Chỉ nhà mạng"]'::jsonb,0,'Bảo vệ trẻ online – việc của tất cả.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(152,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật BVDLCN, chủ thể dữ liệu có nghĩa vụ nào với dữ liệu của người khác?','["Chỉ phải bảo vệ dữ liệu người thân", "Được tự do chia sẻ nếu là bạn bè", "Không có nghĩa vụ", "Tôn trọng, bảo vệ dữ liệu cá nhân của người khác"]'::jsonb,3,'Bảo vệ dữ liệu mình, tôn trọng dữ liệu người.','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(153,3,3,ARRAY['tin-gia']::text[],'img/tingia.svg','Đăng bản đồ Việt Nam thể hiện sai chủ quyền quốc gia trên mạng là?','["Lỗi thiết kế vô hại", "Tự do sáng tác", "Thông tin bị Luật ANM 2025 xác định là xâm phạm an ninh quốc gia", "Chỉ vi phạm nếu in ra giấy"]'::jsonb,2,'Bản đồ Tổ quốc – không “vẽ bậy”.','Điểm e khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(154,3,2,ARRAY['link-la']::text[],'img/linkla.svg','Doanh nghiệp cung cấp dịch vụ thư điện tử phải làm gì với phần mềm độc hại theo Luật ANM 2025?','["Có hệ thống lọc phần mềm độc hại khi gửi, nhận, lưu trữ thông tin", "Không cần làm gì", "Chuyển trách nhiệm cho người dùng", "Chỉ cảnh báo khi người dùng hỏi"]'::jsonb,0,'Hộp thư có “lưới lọc” – luật yêu cầu.','Khoản 3 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(155,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Bà Tư nhận cuộc gọi "công an" báo con trai liên quan đường dây ma túy, yêu cầu chuyển tiền "tạm giữ" vào tài khoản an toàn. Phản ứng đúng?','["Chuyển ngay để con khỏi bị bắt", "Cung cấp số tài khoản để họ kiểm tra", "Cúp máy, không chuyển tiền, liên hệ trực tiếp công an địa phương để xác minh", "Chuyển một nửa để thử"]'::jsonb,2,'Công an không làm việc qua điện thoại đòi chuyển tiền.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(156,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Một "nhân viên ngân hàng" gọi tới, đọc đúng họ tên, số căn cước của bạn rồi xin mã OTP để "hoàn tiền". Điều bạn nên suy luận?','["Đọc thêm số thẻ để họ đối chiếu", "Đưa OTP vì để hoàn tiền", "Họ biết số căn cước nên chắc là thật", "Biết thông tin của bạn không chứng minh họ là thật – dữ liệu có thể đã bị lộ; không đưa OTP"]'::jsonb,3,'Họ biết về bạn ≠ họ là người tốt.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(157,4,3,ARRAY['lua-dao']::text[],'img/luadao.svg','Ứng dụng "đầu tư nhiệm vụ: thả tim video nhận hoa hồng" cho rút lãi 2 lần rồi đòi nạp 50 triệu để "mở khóa". Mô hình này là?','["Đầu tư sinh lời thật", "Lừa đảo chiếm đoạt tài sản điển hình – dừng nạp, lưu bằng chứng, trình báo", "Nạp thêm để rút hết", "Lỗi hệ thống tạm thời"]'::jsonb,1,'Rút được lần đầu là mồi câu lần sau.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(158,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Bạn được mời làm "cộng tác viên", chỉ cần cho thuê tài khoản ngân hàng, mỗi tháng 3 triệu. Rủi ro pháp lý?','["Cho thuê, mua bán tài khoản ngân hàng là trái luật; chủ tài khoản có thể bị xử lý", "Chỉ người thuê chịu trách nhiệm", "Không rủi ro nếu không hỏi mục đích", "Thu nhập thụ động hợp pháp"]'::jsonb,0,'Thuê tài khoản = thuê luôn án phạt.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(159,4,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Kế toán nhận video call "giám đốc" yêu cầu chuyển gấp 2 tỷ cho đối tác, hình ảnh mờ, mạng chập chờn. Quy trình đúng?','["Xác minh qua kênh độc lập (gọi số đã biết, gặp trực tiếp) và tuân thủ quy trình phê duyệt", "Hỏi giám đốc ngày sinh qua chính cuộc gọi đó", "Chuyển ngay vì giám đốc ra lệnh", "Chuyển trước, báo cáo sau"]'::jsonb,0,'Deepfake sợ nhất câu: “Để em gọi lại”.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(160,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Cửa hàng bắt khách để lại số điện thoại mới bán hàng, rồi chia sẻ danh sách cho bên quảng cáo. Sai ở đâu?','["Chỉ sai nếu bán giá cao", "Không có sự đồng ý rõ ràng theo từng mục đích; chia sẻ/mua bán dữ liệu trái luật", "Không sai vì khách tự cho số", "Sai vì không in hóa đơn"]'::jsonb,1,'Cho số để mua hàng ≠ đồng ý bị spam.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(161,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Phụ huynh đăng ảnh con kèm tên trường, lớp, giờ tan học lên mạng công khai. Theo cẩm nang, rủi ro?','["Chỉ rủi ro nếu ảnh xấu", "Tăng nguy cơ kẻ xấu tiếp cận trẻ – nên hạn chế công khai thông tin nhận dạng", "Giúp con nổi tiếng", "Không rủi ro gì"]'::jsonb,1,'Khoe con vừa đủ – đừng khoe lộ trình.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 1 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(162,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Ứng dụng xem phim yêu cầu ảnh chụp căn cước để "xác minh". Bạn là người dùng mạng xã hội, căn cứ nào để từ chối?','["Luật BVDLCN cấm mạng xã hội yêu cầu ảnh/video chứa giấy tờ tùy thân làm yếu tố xác thực tài khoản", "Phải gửi theo quy định", "Không có căn cứ", "Chỉ được từ chối nếu dưới 18 tuổi"]'::jsonb,0,'Căn cước không phải vé xem phim.','Khoản 2 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(163,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Doanh nghiệp tuyển dụng có được tự ý dùng hồ sơ ứng viên trượt để quảng cáo dịch vụ khác không?','["Được vì ứng viên đã nộp", "Được nếu sau 1 năm", "Không – dữ liệu chỉ xử lý theo mục đích đã được đồng ý", "Được nếu không ghi tên"]'::jsonb,2,'Nộp CV để xin việc, không phải để nhận quảng cáo.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(164,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một công ty nhận yêu cầu xóa dữ liệu của khách hàng nhưng cố tình trì hoãn, gây khó khăn. Theo Luật BVDLCN?','["Được trì hoãn vô thời hạn", "Tổ chức có trách nhiệm tạo điều kiện, không được gây khó khăn việc thực hiện quyền của chủ thể dữ liệu", "Chỉ phải xử lý nếu khách trả phí", "Không có quy định"]'::jsonb,1,'Quyền của khách – doanh nghiệp phải mở cửa.','Khoản 4 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 5 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(165,4,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Bạn nhận video "thực phẩm X gây ung thư" từ nhóm họ hàng, chưa rõ nguồn. Ứng xử của người trưởng thành?','["Kiểm chứng qua nguồn chính thống, không chuyển tiếp khi chưa rõ", "Thêm bình luận phóng đại", "Chuyển tiếp để “thà nhầm còn hơn bỏ sót”", "Đăng lên nhóm kinh doanh"]'::jsonb,0,'“Thà nhầm” có thể làm người khác thiệt thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(166,4,3,ARRAY['tin-gia']::text[],'img/tingia.svg','Nghị định 328/2026/NĐ-CP về phòng, chống tin giả, tin sai sự thật có hiệu lực từ ngày nào?','["01/01/2026", "01/7/2026", "19/8/2026", "05/10/2026"]'::jsonb,3,'Tin giả “chính thức có luật chơi” từ 5/10/2026.','Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(167,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','7 nghị định hướng dẫn Luật ANM 2025 được ban hành cùng ngày nào?','["10/12/2025", "19/8/2026", "01/7/2026", "05/10/2026"]'::jsonb,1,'Bảy nghị định – một ngày 19/8.','Nghị định 333/2026/NĐ-CP (quy định chi tiết và biện pháp thi hành Luật An ninh mạng)','ORIGINAL'),
(168,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','Nghị định nào quy định về lực lượng bảo vệ an ninh mạng?','["Nghị định 332/2026/NĐ-CP", "Nghị định 328/2026/NĐ-CP", "Nghị định 329/2026/NĐ-CP", "Nghị định 330/2026/NĐ-CP"]'::jsonb,2,'Lực lượng – “ba hai chín”.','Nghị định 329/2026/NĐ-CP (lực lượng bảo vệ an ninh mạng)','ORIGINAL'),
(169,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','Doanh nghiệp kinh doanh sản phẩm, dịch vụ an ninh mạng cần đọc kỹ nghị định nào?','["Nghị định 328/2026/NĐ-CP", "Nghị định 332/2026/NĐ-CP", "Nghị định 329/2026/NĐ-CP", "Nghị định 327/2026/NĐ-CP"]'::jsonb,1,'Kinh doanh bảo mật – “ba ba hai”.','Nghị định 332/2026/NĐ-CP (kinh doanh sản phẩm, dịch vụ an ninh mạng)','ORIGINAL'),
(170,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','Bảo vệ an ninh mạng đối với hệ thống thông tin được hướng dẫn chi tiết tại?','["Nghị định 331/2026/NĐ-CP", "Nghị định 329/2026/NĐ-CP", "Nghị định 330/2026/NĐ-CP", "Nghị định 328/2026/NĐ-CP"]'::jsonb,0,'Hệ thống thông tin – “ba ba mốt”.','Nghị định 331/2026/NĐ-CP (bảo vệ an ninh mạng đối với hệ thống thông tin)','ORIGINAL'),
(171,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Nghị định 327/2026/NĐ-CP tập trung vào nội dung nào?','["Lực lượng bảo vệ an ninh mạng", "Phòng ngừa, xử lý thông tin và hành vi dùng CNTT, phương tiện điện tử xâm phạm an ninh quốc gia, trật tự, an toàn xã hội", "Kinh doanh dịch vụ an ninh mạng", "Xử phạt bảo vệ dữ liệu cá nhân"]'::jsonb,1,'327 – “chặn” thông tin xâm phạm.','Nghị định 327/2026/NĐ-CP (phòng ngừa, xử lý thông tin xâm phạm ANQG, TTATXH trên không gian mạng)','ORIGINAL'),
(172,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','Nghị định quy định chi tiết một số điều và biện pháp thi hành Luật ANM là?','["Nghị định 333/2026/NĐ-CP", "Nghị định 330/2026/NĐ-CP", "Nghị định 327/2026/NĐ-CP", "Nghị định 331/2026/NĐ-CP"]'::jsonb,0,'Ba ba ba – “bản đồ” thi hành luật.','Nghị định 333/2026/NĐ-CP (quy định chi tiết và biện pháp thi hành Luật An ninh mạng)','ORIGINAL'),
(173,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Luật ANM 2025 gộp nội dung của những luật nào trước đây?','["Bộ luật Hình sự và Luật Tố cáo", "Luật Viễn thông và Luật Báo chí", "Luật An ninh mạng 2018 và Luật An toàn thông tin mạng 2015", "Luật Giao dịch điện tử và Luật Công nghệ thông tin"]'::jsonb,2,'Hai luật cũ “hợp nhất” thành một.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(174,4,2,ARRAY['hack']::text[],'img/hack.svg','Nhân viên tò mò dùng tài khoản quản trị để xem hồ sơ lương đồng nghiệp ngoài phạm vi công việc. Đánh giá?','["Truy cập, xử lý dữ liệu cá nhân trái quy định – vi phạm", "Chỉ vi phạm nội quy", "Không sao nếu không kể ai", "Được phép vì có quyền quản trị"]'::jsonb,0,'Có chìa khóa không có nghĩa được mở mọi cửa.','Khoản 4 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(175,4,3,ARRAY['hack']::text[],'img/hack.svg','Công ty bị tấn công ransomware, dữ liệu khách hàng bị lộ. Theo Luật BVDLCN, việc cần làm có tính pháp lý?','["Đổ lỗi cho nhân viên IT trên mạng", "Giấu kín để giữ uy tín", "Thông báo vi phạm quy định về bảo vệ dữ liệu cá nhân theo quy định", "Trả tiền chuộc rồi im lặng"]'::jsonb,2,'Lộ dữ liệu – phải thông báo, không được giấu.','Điều 23 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(176,4,2,ARRAY['hack']::text[],'img/hack.svg','Gây sự cố, chiếm quyền điều khiển, làm tê liệt hệ thống thông tin là?','["Sơ suất kỹ thuật", "Không bị điều chỉnh", "Hành vi bị nghiêm cấm về an ninh mạng", "Kiểm thử bảo mật hợp lệ dù không xin phép"]'::jsonb,2,'Không xin phép mà “thử” – là tấn công.','Khoản 3 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(177,4,3,ARRAY['hack']::text[],'img/hack.svg','Chủ quản hệ thống thông tin có trách nhiệm gì với các hành vi tấn công mạng?','["Chỉ mua bảo hiểm", "Chờ công an xử lý", "Áp dụng biện pháp kỹ thuật để phòng ngừa, ngăn chặn đối với hệ thống thuộc phạm vi quản lý", "Không có trách nhiệm"]'::jsonb,2,'Hệ thống của ai – người đó gác cổng.','Khoản 2 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(178,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Người cao tuổi trong nhà nhận tin "trúng thưởng ô tô, nộp phí 5 triệu để nhận". Con cháu nên làm gì?','["Giải thích dấu hiệu lừa đảo, cùng kiểm tra và không nộp tiền", "Nộp một nửa", "Nộp giúp cho ông bà vui", "Chia sẻ lên mạng hỏi ý kiến"]'::jsonb,0,'Trúng thưởng mà phải nộp phí – trúng bẫy.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(179,4,3,ARRAY['lua-dao']::text[],'img/luadao.svg','Website giả mạo cổng dịch vụ công yêu cầu nhập thông tin định danh để "cập nhật dữ liệu". Hành vi tạo website này vi phạm?','["Không vi phạm vì chưa lấy được gì", "Là lỗi DNS", "Giả mạo trang thông tin điện tử của cơ quan, tổ chức – bị nghiêm cấm", "Chỉ vi phạm bản quyền giao diện"]'::jsonb,2,'Giống cổng công ≠ cổng công.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(180,4,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Chủ nhà trọ lắp camera hướng vào phòng ở của người thuê. Theo Luật BVDLCN?','["Không có quy định", "Xâm phạm dữ liệu cá nhân thu được từ ghi hình; cần tuân thủ quy định về ghi âm, ghi hình nơi công cộng và quyền riêng tư", "Được phép nếu không ghi âm", "Được phép vì là nhà của chủ"]'::jsonb,1,'Camera an ninh không phải camera nhìn trộm.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 4 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(181,4,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn là admin nhóm phụ huynh. Một thành viên đăng bài xúc phạm cô giáo. Ứng xử phù hợp?','["Chia sẻ sang nhóm khác", "Ẩn/gỡ bài, nhắc nhở, hướng dẫn phản ánh qua kênh chính thức", "Để nguyên cho tự do ngôn luận", "Ghim bài lên đầu"]'::jsonb,1,'Admin nhóm – người gác cổng văn minh.','Điểm d khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(182,4,3,ARRAY['bat-nat']::text[],'img/batnat.svg','Khi trẻ kể bị xâm hại trực tuyến, cẩm nang khuyên người lớn có nên thu ngay điện thoại của trẻ?','["Không nên phản ứng trừng phạt; ưu tiên lắng nghe, trấn an, cùng xử lý", "Có, và la mắng để trẻ nhớ", "Không, và bỏ qua chuyện đó", "Có, thu ngay và cấm dùng mạng"]'::jsonb,0,'Thu điện thoại có thể làm trẻ không bao giờ kể nữa.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(183,4,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Câu nói nào cẩm nang khuyên người lớn nên dùng khi trẻ lần đầu kể chuyện?','["\"Sao con dại thế?\"", "\"Chuyện nhỏ, quên đi\"", "\"Cảm ơn con đã kể, đây không phải lỗi của con\"", "\"Ai bảo con lên mạng\""]'::jsonb,2,'Câu đầu tiên quyết định trẻ có kể tiếp hay không.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(184,4,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Phụ huynh đăng ký tài khoản mạng xã hội cho con 10 tuổi bằng thông tin của con và để con tự dùng. Theo Luật ANM?','["Đúng vì là tài khoản của con", "Đúng nếu con học giỏi", "Luật không quy định", "Chưa đúng – cha mẹ đăng ký bằng thông tin của mình và có trách nhiệm giám sát nội dung trẻ truy cập"]'::jsonb,3,'Con online – bố mẹ đứng tên và đồng hành.','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(185,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một nhà trường muốn công khai danh sách học sinh vi phạm kèm ảnh trên fanpage. Cần lưu ý gì?','["Không cần lưu ý", "Được làm vì mục đích giáo dục", "Xử lý dữ liệu, công bố đời tư trẻ em từ đủ 7 tuổi cần đồng ý của trẻ và người đại diện; cân nhắc quyền trẻ em", "Chỉ cần hiệu trưởng ký"]'::jsonb,2,'Giáo dục không cần “bêu” lên mạng.','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(186,4,2,ARRAY['mua-sam']::text[],'img/muasam.svg','Bạn bán hàng online, chụp màn hình tin nhắn khách "bom hàng" kèm số điện thoại, địa chỉ để bêu lên nhóm. Đánh giá?','["Cảnh báo cộng đồng nên không sao", "Công khai dữ liệu cá nhân trái luật – có thể vi phạm", "Hợp pháp vì khách sai trước", "Quyền của người bán"]'::jsonb,1,'Bị bom hàng – vẫn không được “bom” dữ liệu khách.','Khoản 4 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(187,4,2,ARRAY['mua-sam']::text[],'img/muasam.svg','Livestream bán hàng giả nhãn hiệu nổi tiếng trên mạng xã hội. Theo Luật ANM 2025?','["Không bị điều chỉnh vì là livestream", "Kinh doanh bình thường", "Là hành vi mạo danh, làm nhái nhãn hiệu và quảng cáo hàng giả trên không gian mạng", "Chỉ vi phạm khi bị kiện"]'::jsonb,2,'Hàng nhái online – vi phạm thật.','Điểm c khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm h khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(188,4,3,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Dùng thông tin của người khác để đăng ký tài khoản ví điện tử là?','["Không có quy định", "Chỉ vi phạm nếu có tiền trong ví", "Hành vi xâm phạm trật tự, an toàn xã hội trên không gian mạng", "Tiện lợi hợp pháp"]'::jsonb,2,'Ví đứng tên người khác – rắc rối đứng tên mình.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(189,4,2,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Thói quen nào giúp người trưởng thành giảm rủi ro khi bị lộ một mật khẩu?','["Lưu mật khẩu trong tin nhắn Zalo", "Mật khẩu khác nhau cho từng dịch vụ, dùng trình quản lý mật khẩu và bật xác thực 2 lớp", "Một mật khẩu thật dài cho tất cả", "Đổi mật khẩu thành ngày sinh con"]'::jsonb,1,'Mỗi cửa một chìa – mất một chìa không mất cả nhà.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(190,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Dữ liệu cá nhân nhạy cảm theo Luật BVDLCN là gì?','["Do mỗi công ty tự quy định", "Dữ liệu gắn liền với quyền riêng tư, khi bị xâm phạm ảnh hưởng trực tiếp đến quyền, lợi ích hợp pháp; thuộc danh mục do Chính phủ ban hành", "Chỉ dữ liệu sức khỏe", "Mọi dữ liệu trên mạng"]'::jsonb,1,'Nhạy cảm – có danh mục, không tùy hứng.','Khoản 3 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(191,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Mạng xã hội phải cung cấp lựa chọn nào liên quan đến theo dõi hoạt động người dùng?','["Lựa chọn \"không theo dõi\" hoặc chỉ theo dõi khi người dùng đồng ý", "Không cần lựa chọn nào", "Chỉ cho người trả phí", "Theo dõi mặc định không tắt được"]'::jsonb,0,'Không muốn bị theo dõi – phải có nút tắt.','Khoản 4 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(192,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Bạn nhận email "hóa đơn điện nước tháng này" kèm file nén có mật khẩu. Đây có thể là thủ đoạn gì?','["Phát tán mã độc qua file đính kèm né bộ lọc", "Lỗi gửi thư", "Hóa đơn bình thường", "Khuyến mãi điện lực"]'::jsonb,0,'File nén có mật khẩu từ lạ – né quét, gài mã độc.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(193,4,3,ARRAY['hack']::text[],'img/hack.svg','Mua bán, trao đổi công cụ phần mềm "hack Facebook" để chiếm tài khoản người khác thuộc hành vi?','["Liên quan tấn công mạng – bị nghiêm cấm", "Kinh doanh phần mềm hợp pháp", "Dịch vụ phục hồi tài khoản", "Không bị cấm nếu không tự dùng"]'::jsonb,0,'Bán công cụ hack – cũng là tấn công mạng.','Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15; Khoản 4 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(194,4,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Phản ánh sai lệch đường biên giới quốc gia trong bài đăng du lịch là?','["Không có quy định", "Thông tin xâm phạm an ninh quốc gia theo Luật ANM 2025", "Sơ suất không quan trọng", "Tự do sáng tạo nghệ thuật"]'::jsonb,1,'Bản đồ du lịch cũng phải đúng chủ quyền.','Điểm e khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(195,4,3,ARRAY['tin-gia']::text[],'img/tingia.svg','Người có ảnh hưởng (KOL) chia sẻ thông tin sai sự thật về một doanh nghiệp, gây thiệt hại. Theo Luật ANM 2025?','["Quyền đánh giá sản phẩm", "Không sao nếu đã xin lỗi", "Lan truyền thông tin xuyên tạc, bịa đặt ảnh hưởng uy tín tổ chức là thông tin xâm phạm quyền, lợi ích hợp pháp", "Chỉ doanh nghiệp tự chịu"]'::jsonb,2,'Ảnh hưởng lớn – trách nhiệm lớn.','Điểm a khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(196,4,2,ARRAY['bao-cao']::text[],'img/baocao.svg','Khi phát hiện tài khoản phát tán nội dung xâm hại trẻ em, người lớn nên tránh điều gì?','["Chuyển tiếp nội dung cho nhiều người \"để cảnh báo\"", "Báo công an", "Báo cáo nền tảng", "Gọi Tổng đài 111"]'::jsonb,0,'Cảnh báo bằng cách lan truyền = gây hại thêm.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(197,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Biện pháp bảo vệ an ninh mạng và trách nhiệm quản lý nhà nước được Luật ANM 2025 quy định – theo luật, ai chủ trì phòng, chống tấn công mạng đối với hệ thống thông tin quân sự?','["Ban Cơ yếu Chính phủ", "Bộ Công an", "Bộ Quốc phòng", "UBND cấp tỉnh"]'::jsonb,2,'Hệ thống quân sự – Bộ Quốc phòng chủ trì.','Điểm b khoản 4 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(198,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Theo Luật ANM 2025, ai chủ trì phòng ngừa, phát hiện, xử lý phần mềm độc hại gây tổn hại tới an ninh quốc gia?','["Bộ Công an, phối hợp Bộ Quốc phòng và các bộ, ngành", "Bộ Giáo dục", "Mỗi người dân", "Các nhà mạng tự quyết"]'::jsonb,0,'Mã độc đe dọa an ninh quốc gia – Bộ Công an chủ trì.','Khoản 5 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(199,4,2,ARRAY['luat-chung']::text[],'img/luat.svg','UBND cấp tỉnh có trách nhiệm gì về phổ biến kiến thức an ninh mạng?','["Không có trách nhiệm", "Chỉ cấp phép mạng", "Xây dựng, triển khai hoạt động phổ biến, nâng cao nhận thức cho cơ quan, tổ chức, cá nhân của địa phương", "Chỉ xử phạt"]'::jsonb,2,'Tỉnh nào cũng phải “dạy” an ninh mạng.','Khoản 3 Điều 35 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(200,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Các hoạt động sau đều là "xử lý dữ liệu cá nhân" theo Luật BVDLCN, TRỪ?','["Chuyển giao", "Thu thập", "Một người tự nhớ tên bạn mình trong đầu", "Khử nhận dạng"]'::jsonb,2,'Xử lý dữ liệu: thu, phân tích, mã hóa, xóa, chuyển giao…','Khoản 6 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(201,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật BVDLCN, sự đồng ý phải được thể hiện thế nào?','["Chỉ cần gật đầu qua điện thoại", "Rõ ràng, cụ thể, có thể in, sao chép bằng văn bản, kể cả dạng điện tử kiểm chứng được", "Mặc định khi tải app", "Do bên thu thập tự suy đoán"]'::jsonb,1,'Đồng ý phải “để lại dấu vết”.','Khoản 3 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(202,4,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Đồng nghiệp ghi âm lén cuộc gọi Zalo giữa bạn và sếp rồi gửi vào nhóm công ty. Đánh giá?','["Ghi âm trái phép cuộc đàm thoại trên không gian mạng là bị nghiêm cấm", "Chỉ vi phạm nội quy", "Quyền lưu bằng chứng", "Không sao vì là chuyện công việc"]'::jsonb,0,'Ghi lén rồi phát – hai lần sai.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(203,4,3,ARRAY['lua-dao']::text[],'img/luadao.svg','Dấu hiệu chung của các chiêu lừa đảo trực tuyến mà người trưởng thành nên nhận ra?','["Luôn gọi từ số nước ngoài", "Tạo cảm giác gấp gáp, hứa lợi lớn hoặc đe dọa, và yêu cầu chuyển tiền/OTP/thông tin", "Luôn có lỗi chính tả", "Chỉ nhắm vào người già"]'::jsonb,1,'Gấp + lợi + đòi tiền = dừng lại.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(204,4,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Phụ huynh muốn bảo vệ con khỏi dụ dỗ qua game. Cách hiệu quả nhất theo cẩm nang?','["Cấm hoàn toàn internet", "Mặc kệ vì con còn nhỏ", "Đọc trộm mọi tin nhắn của con", "Trò chuyện thường xuyên, thiết lập quyền riêng tư, để con biết luôn có thể kể mà không bị trách"]'::jsonb,3,'Kết nối với con trước khi con kết nối với người lạ.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(205,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Luật ANM 2025 gồm bao nhiêu điều (theo văn bản đăng Công báo)?','["45 điều", "58 điều", "39 điều", "43 điều"]'::jsonb,0,'Bốn mươi lăm điều – gọn mà đủ.','Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(206,4,3,ARRAY['luat-chung']::text[],'img/luat.svg','Luật BVDLCN 2025 gồm bao nhiêu điều?','["45 điều", "30 điều", "58 điều", "39 điều"]'::jsonb,3,'Ba mươi chín điều bảo vệ dữ liệu.','Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL')
